1	<!doctype html>
2	<html lang="sv">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Alunix, webbyrå. Er hemsida är nutidens visitkort</title>
7	<meta name="description" content="Alunix är en webbyrå i Sverige. Webbdesign, design och system. Allt på ett ställe.">
8	<link rel="preconnect" href="https://fonts.googleapis.com">
9	<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
10	<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Archivo:wdth,wght@100,900&family=Familjen+Grotesk:wght@400;500;600&display=swap">
11	<script>document.documentElement.classList.add('js');</script>
12	<style>
13	/* ---------- Affischen: fem färger, två typsnitt, en yta ---------- */
14	:root{
15	  --paper:#CBD3C9;   /* salviapapper */
16	  --ink:#1B1F1C;     /* bläck */
17	  --white:#F5F6F2;   /* ovanpå papperet: bara plåtar */
18	  --line:#A7B0A5;    /* hårlinje, stark */
19	  --line2:#BFC7BC;   /* hårlinje, svag */
20	  --m:clamp(20px,2.4vw,34px);
21	  --bar:52px;
22	  --poster:clamp(38px,9.5vw,170px);
23	  --read:17px;
24	  --gut:24px;
25	  --maxw:1680px;
26	}
27	@media (max-width:899px){ :root{ --poster:12vw; --bar:48px; --gut:16px } }
28	
29	*,*::before,*::after{ box-sizing:border-box }
30	html{ background:var(--paper); color:var(--ink); -webkit-text-size-adjust:100% }
31	body{ margin:0; font:400 var(--read)/1.45 "Familjen Grotesk", "Helvetica Neue", Arial, sans-serif; background:var(--paper); color:var(--ink); overflow-x:clip }
32	img,svg,iframe{ display:block; max-width:100% }
33	img{ height:auto }
34	a{ color:inherit; text-decoration:none }
35	a:hover{ text-decoration:underline; text-underline-offset:.18em }
36	:focus-visible{ outline:2px solid var(--ink); outline-offset:3px }
37	.sr-only{ position:absolute; width:1px; height:1px; overflow:hidden; clip:rect(0 0 0 0); white-space:nowrap }
38	
39	.label{ font-size:12px; line-height:1.4; font-weight:500; letter-spacing:.14em; text-transform:uppercase }
40	.poster{ font-family:Archivo, "Arial Black", sans-serif; font-weight:900; font-stretch:100%; font-size:var(--poster); line-height:.9; letter-spacing:-.02em; margin:0 }
41	.wrap{ max-width:var(--maxw); margin:0 auto; padding:0 var(--m) }
42	
43	/* ---------- toppbar ---------- */
44	.bar{ position:sticky; top:0; z-index:20; background:var(--paper); border-bottom:1px solid var(--line) }
45	.bar .wrap{ height:var(--bar); display:flex; align-items:center; gap:var(--gut) }
46	.bar .mark{ display:flex; align-items:center; gap:10px; margin-right:auto }
47	.bar .mark img{ width:16px; height:22px }
48	.bar .clock{ font-variant-numeric:tabular-nums; display:flex; gap:.6em }
49	.bar .clock time:empty{ display:none }
50	.bar .mail{ font-weight:500 }
51	@media (max-width:599px){ .bar .clock .city{ display:none } .bar .mark .label{ display:none } }
52	
53	/* ---------- akt 1 till 3: affischen, bytet, andningen ---------- */
54	.hero{ position:relative }
55	.js:not(.rm) .hero{ height:320vh }
56	.stage{ position:sticky; top:var(--bar); height:calc(100vh - var(--bar)); overflow:clip; display:flex; flex-direction:column }
57	.js.rm .stage{ height:auto; min-height:0 }
58	@media (max-width:899px){ .stage{ height:auto } }
59	html:not(.js) .stage{ position:static; height:auto }
60	.stage .desc{ margin:clamp(16px,2.6vh,28px) 0 clamp(14px,2.2vh,24px); font-size:clamp(17px,1.5vw,22px); line-height:1.35; max-width:40ch }
61	
62	.block{ position:relative; transform-origin:0 0; will-change:transform }
63	.row{ position:relative; clip-path:inset(0 0 0 0); width:100% }
64	.face{ position:absolute; left:0; top:0 }
65	.fa{ display:block }
66	.fa svg{ width:var(--svgw, 100%); height:auto; overflow:visible }
67	.fa svg text{ font-family:Archivo, "Arial Black", sans-serif; font-weight:900; font-stretch:100%; font-size:100px; letter-spacing:-2px; fill:var(--ink) }
68	.fb{ transform-origin:0 0; white-space:normal }
69	.fb .poster{ display:block }
70	/* utan JS eller med reduced motion: raderna ligger i flödet, ingen rullning, ingen skalning */
71	html:not(.js) .row,.rm .row{ clip-path:none !important; height:auto !important; width:auto !important }
72	html:not(.js) .face,.rm .face{ position:static; transform:none !important; opacity:1 !important }
73	html:not(.js) .fb,.rm .fb{ display:none }
74	html:not(.js) .block,.rm .block{ transform:none !important; height:auto !important; margin-top:0 !important; width:min(100%, 68vh) }
75	@media (max-width:899px){ html:not(.js) .block,.rm .block{ width:100% } }
76	.rm .row + .row, html:not(.js) .row + .row{ margin-top:-1px }
77	
78	.stage .under{ position:relative; margin:18px 0 0 }
79	.stage .site{ margin:0 }
80	.stage .lead{ position:absolute; left:0; top:0; opacity:0; max-width:40ch }
81	.rm .stage .lead, html:not(.js) .stage .lead{ display:none }
82	.hero-foot{ margin-top:auto; padding:24px 0 var(--m); display:grid; grid-template-columns:1fr minmax(0, 34ch); gap:var(--gut); align-items:end }
83	.hero-foot .claim{ grid-column:2 }
84	.claim .h1{ margin:0 0 .35em; font-weight:600; line-height:1.3 }
85	.claim p{ margin:0 }
86	.lead p{ margin:0 }
87	.lead .label{ margin-bottom:.6em }
88	@media (max-width:899px){
89	  .hero-foot{ grid-template-columns:1fr; gap:18px }
90	  .hero-foot .claim{ grid-column:1 }
91	  .stage .desc{ font-size:16px }
92	}
93	
94	/* ---------- akt 4: bevis ---------- */
95	.bevis{ padding-top:clamp(40px,8vh,96px); padding-bottom:clamp(32px,6vh,72px); overflow-x:clip }
96	.static-heading{ margin:0 0 .5em }
97	.js:not(.rm) .static-heading{ display:none }
98	.bevis .intro{ display:none; margin:0 0 3em; max-width:40ch }
99	.rm .bevis .intro, html:not(.js) .bevis .intro{ display:block }
100	.spread{ display:grid; grid-template-columns:repeat(12,minmax(0,1fr)); column-gap:var(--gut); row-gap:14px; margin:0 0 clamp(48px,10vh,120px) }
101	.spread:last-child{ margin-bottom:0 }
102	.spread .plate, .spread .cap{ grid-column:1/11 }
103	.spread:nth-child(even) .plate, .spread:nth-child(even) .cap{ grid-column:3/13 }
104	.plate{ position:relative; aspect-ratio:16/10; background:var(--white); border:1px solid var(--line); border-radius:2px; overflow:hidden }
105	.plate iframe{ position:absolute; inset:0; width:100%; height:100%; border:0; background:var(--white) }
106	.plate .shot{ position:absolute; inset:0; width:100%; height:100%; object-fit:cover; object-position:top; z-index:1 }
107	.rm .plate .shot{ display:none }
108	.js:not(.rm) .plate .shot{ filter:grayscale(1) }
109	.js:not(.rm) .plate .shot.open{ opacity:0; pointer-events:none; transition:opacity .5s ease }
110	.cap{ display:flex; justify-content:space-between; gap:var(--gut); border-top:1px solid var(--line2); padding-top:10px }
111	.cap .arrow{ white-space:nowrap }
112	.js:not(.rm) .spread .plate, .js:not(.rm) .spread .cap{ opacity:0; transform:translateX(-48px); transition:opacity .9s ease, transform .9s ease }
113	.js:not(.rm) .spread:nth-child(even) .plate, .js:not(.rm) .spread:nth-child(even) .cap{ transform:translateX(48px) }
114	.js:not(.rm) .spread .cap{ transition-delay:.15s }
115	.js:not(.rm) .spread.in .plate, .js:not(.rm) .spread.in .cap{ opacity:1; transform:none }
116	@media (max-width:699px){
117	  .spread .plate, .spread .cap, .spread:nth-child(even) .plate, .spread:nth-child(even) .cap{ grid-column:1/-1 }
118	  .plate{ aspect-ratio:4/5 }
119	  .cap{ flex-direction:column; gap:6px }
120	}
121	
122	/* ---------- akt 5 och 6: liggaren ---------- */
123	.ledger{ padding-top:clamp(40px,8vh,96px); padding-bottom:clamp(40px,8vh,96px) }
124	.ledger .head{ display:grid; grid-template-columns:repeat(12,minmax(0,1fr)); column-gap:var(--gut); align-items:end; margin-bottom:clamp(24px,4vh,40px) }
125	.ledger .head .head-text{ grid-column:1/7 }
126	.ledger .head .label{ margin:0 }
127	.ledger .head p.line{ margin:.8em 0 0; max-width:36ch }
128	.ledger .head figure{ grid-column:10/13; margin:0 }
129	.ledger .head figure img{ width:100%; border-radius:2px; border:1px solid var(--line) }
130	.ledger .head figcaption{ margin-top:8px; color:var(--ink) }
131	.rm .ledger .head figure img, html:not(.js) .ledger .head figure img{ transform:none !important }
132	.ledger ol, .ledger ul{ list-style:none; margin:0; padding:0; border-top:1px solid var(--line) }
133	.ledger ul{ overflow-x:clip }
134	.lrow{ display:grid; grid-template-columns:minmax(0,2.5fr) minmax(0,2.5fr) minmax(0,7fr); column-gap:var(--gut); align-items:baseline; padding:clamp(14px,2.4vh,28px) 0; border-bottom:1px solid var(--line) }
135	.lrow .num{ font-variant-numeric:tabular-nums }
136	.lrow .name{ margin:0 }
137	.lrow p{ margin:0; max-width:44ch }
138	.js:not(.rm) .lrow{ clip-path:inset(0 100% 0 0); transition:clip-path .9s cubic-bezier(.2,.7,.2,1) }
139	.js:not(.rm) .lrow.in{ clip-path:inset(0 0 0 0) }
140	.prow{ display:grid; grid-template-columns:minmax(0,9fr) minmax(0,3fr); column-gap:var(--gut); align-items:baseline; padding:clamp(14px,2.4vh,24px) 0; border-bottom:1px solid var(--line) }
141	.prow p{ margin:0; max-width:56ch }
142	.prow .price{ text-align:right; font-weight:600; font-variant-numeric:tabular-nums; white-space:nowrap }
143	.js:not(.rm) .prow{ opacity:0; transition:opacity .7s ease }
144	.js:not(.rm) .prow .price{ transform:translateX(28px); transition:transform .7s cubic-bezier(.2,.7,.2,1) }
145	.js:not(.rm) .prow.in{ opacity:1 }
146	.js:not(.rm) .prow.in .price{ transform:none }
147	@media (max-width:699px){
148	  .ledger .head{ row-gap:20px }
149	  .ledger .head .head-text{ grid-column:1/-1 }
150	  .ledger .head figure{ grid-column:1/8 }
151	  .lrow{ grid-template-columns:minmax(0,1fr); row-gap:6px }
152	  .prow{ grid-template-columns:minmax(0,1fr); row-gap:4px }
153	  .prow .price{ text-align:left }
154	}
155	
156	/* ---------- akt 7: avslutet, inverterat ---------- */
157	.close{ padding-top:clamp(32px,6vh,72px) }
158	.sheet{ background:var(--ink); color:var(--paper); min-height:70vh; display:flex; flex-direction:column; justify-content:flex-end }
159	.js:not(.rm) .sheet{ clip-path:inset(0 100% 0 0) }
160	.sheet .wrap{ width:100%; padding-top:clamp(40px,8vh,96px); padding-bottom:var(--m) }
161	.sheet .poster{ max-width:10.2em }
162	.sheet .mail{ display:inline-block; margin:1.6em 0 2.4em; text-decoration:underline; text-underline-offset:.2em }
163	.sheet .fine{ margin:0; font-size:11px; line-height:1.5; letter-spacing:.02em; max-width:70ch }
164	.sheet .fine a{ text-decoration:underline; text-underline-offset:.15em }
165	
166	@media (prefers-reduced-motion:reduce){
167	  *{ transition:none !important; animation:none !important }
168	}
169	</style>
170	</head>
