322	<script>
323	(function(){
324	  'use strict';
325	  const doc = document.documentElement;
326	  const rmq = matchMedia('(prefers-reduced-motion: reduce)');
327	  let rm = rmq.matches;
328	  if (rm) doc.classList.add('rm');
329	  rmq.addEventListener && rmq.addEventListener('change', e => { rm = e.matches; doc.classList.toggle('rm', rm); layout(); });
330	
331	  /* ---------- klockan: riktig tid i Stockholm ---------- */
332	  const clockEl = document.getElementById('clock');
333	  const fmt = new Intl.DateTimeFormat('sv-SE', { timeZone:'Europe/Stockholm', hour:'2-digit', minute:'2-digit', second:'2-digit', hour12:false });
334	  function tick(){ const d = new Date(); clockEl.textContent = fmt.format(d); clockEl.setAttribute('datetime', d.toISOString()); }
335	  tick(); setInterval(tick, 1000);
336	
337	  /* ---------- element ---------- */
338	  const hero = document.getElementById('hero');
339	  const stage = document.getElementById('stage');
340	  const block = document.getElementById('block');
341	  const rows = [document.getElementById('row1'), document.getElementById('row2')];
342	  const svgs = rows.map(r => r.querySelector('svg'));
343	  const fas = rows.map(r => r.querySelector('.fa'));
344	  const fbs = rows.map(r => r.querySelector('.fb'));
345	  const strips = svgs.map(s => s.querySelector('.strip'));
346	  const foot = document.getElementById('heroFoot');
347	  const siteRow = document.getElementById('siteRow');
348	  const claim = document.getElementById('claim');
349	  const lead = document.getElementById('lead');
350	  const spreads = Array.from(document.querySelectorAll('.spread'));
351	  const shots = spreads.map(s => s.querySelector('.shot'));
352	  const lrows = Array.from(document.querySelectorAll('.lrow'));
353	  const prows = Array.from(document.querySelectorAll('.prow'));
354	  const deskPhoto = document.getElementById('deskPhoto');
355	  const sheet = document.getElementById('sheet');
356	  const siteNames = ['Exempelsida: Calyx, florist i Stockholm','Exempelsida: Hōrai, Asian fusion-koncept','Exempelsida: Hyperborea, konferens i Lund'];
