358	  /* ---------- fönstren i A, U och X: mätta i bläcket, inte gissade ---------- */
359	  const NS = 'http://www.w3.org/2000/svg';
360	  const BASE = 71;                    // baslinjen i SVG-enheter
361	  const scan = document.createElement('canvas'); const sc = scan.getContext('2d', { willReadFrequently:true });
362	  const SC = 2;                       // skannar vid 200 px, enheter är 100 px
363	  function inkScan(ch, fam){
364	    const W = 400, H = 400, penX = 100, penY = 260;
365	    scan.width = W; scan.height = H;
366	    sc.clearRect(0, 0, W, H); sc.font = `900 ${100 * SC}px ${fam}`; sc.textBaseline = 'alphabetic'; sc.fillStyle = '#000';
367	    sc.fillText(ch, penX, penY);
368	    const d = sc.getImageData(0, 0, W, H).data;
369	    const ink = (x, y) => d[(y * W + x) * 4 + 3] > 110;
370	    const runsRow = y => { const r = []; let s = -1; for (let x = 0; x < W; x++){ const k = ink(x, y); if (k && s < 0) s = x; else if (!k && s >= 0){ r.push([s, x - 1]); s = -1; } } if (s >= 0) r.push([s, W - 1]); return r; };
371	    const runsCol = x => { const r = []; let s = -1; for (let y = 0; y < H; y++){ const k = ink(x, y); if (k && s < 0) s = y; else if (!k && s >= 0){ r.push([s, y - 1]); s = -1; } } if (s >= 0) r.push([s, H - 1]); return r; };
372	    // gap = mellan yttersta bläckstråken på en rad (räknare och öppningar), 1.5 enheter in i bläcket
373	    const regionsRows = []; let cur = null;
374	    for (let y = 0; y < H; y++){
375	      const r = runsRow(y); let g = null;
376	      if (r.length >= 2) g = [r[0][1] + 1 - 3, r[r.length - 1][0] + 3];
377	      if (g){ if (cur && y === cur.y1 + 1 && Math.abs(g[0] - cur.l[cur.l.length-1][0]) < 40){ cur.y1 = y; cur.l.push([g[0], y]); cur.r.push([g[1], y]); } else { cur = { y0:y, y1:y, l:[[g[0], y]], r:[[g[1], y]] }; regionsRows.push(cur); } }
378	      else cur = null;
379	    }
380	    const regionsCols = []; cur = null;
381	    for (let x = 0; x < W; x++){
382	      const r = runsCol(x); let g = null;
383	      if (r.length >= 2) g = [r[0][1] + 1 - 3, r[r.length - 1][0] + 3];
384	      if (g){ if (cur && x === cur.x1 + 1 && Math.abs(g[0] - cur.t[cur.t.length-1][0]) < 40){ cur.x1 = x; cur.t.push([g[0], x]); cur.b.push([g[1], x]); } else { cur = { x0:x, x1:x, t:[[g[0], x]], b:[[g[1], x]] }; regionsCols.push(cur); } }
385	      else cur = null;
386	    }
387	    const u = v => v / SC;
388	    // bläckets yttermått, så att öppna sidor (A:s fot, U:s topp, X:s kilar) aldrig visar papper
389	    let iy0 = H, iy1 = 0, ix0 = W, ix1 = 0;
390	    for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) if (ink(x, y)){ if (y < iy0) iy0 = y; if (y > iy1) iy1 = y; if (x < ix0) ix0 = x; if (x > ix1) ix1 = x; }
391	    const polyRows = regionsRows.filter(R => R.y1 - R.y0 > 4).map(R => {
392	      const yTop = Math.max(R.y0 - 3, iy0 + 1), yBot = Math.min(R.y1 + 4, iy1);
393	      const pts = [];
394	      pts.push([R.l[0][0], yTop]);
395	      R.l.forEach(([x, y]) => pts.push([x, y]));
396	      pts.push([R.l[R.l.length - 1][0], yBot], [R.r[R.r.length - 1][0], yBot]);
397	      R.r.slice().reverse().forEach(([x, y]) => pts.push([x, y + 1]));
398	      pts.push([R.r[0][0], yTop]);
399	      return pts.map(([x, y]) => `${u(x - penX)},${u(y - penY)}`).join(' ');
400	    });
401	    const polyCols = regionsCols.filter(R => R.x1 - R.x0 > 4).map(R => {
402	      const xL = Math.max(R.x0 - 3, ix0 + 1), xR = Math.min(R.x1 + 4, ix1);
403	      const pts = [];
404	      pts.push([xL, R.t[0][0]]);
405	      R.t.forEach(([y, x]) => pts.push([x, y]));
406	      pts.push([xR, R.t[R.t.length - 1][0]], [xR, R.b[R.b.length - 1][0]]);
407	      R.b.slice().reverse().forEach(([y, x]) => pts.push([x + 1, y]));
408	      pts.push([xL, R.b[0][0]]);
409	      return pts.map(([x, y]) => `${u(x - penX)},${u(y - penY)}`).join(' ');
410	    });
411	    return { polyRows, polyCols };
412	  }
413	  function buildWindows(){
414	    svgs.forEach(svg => {
415	      const text = svg.querySelector('text');
416	      const mask = svg.querySelector('mask');
417	      const word = svg.dataset.word;
418	      mask.querySelectorAll('.hull').forEach(n => n.remove());
419	      const fam = getComputedStyle(text).fontFamily;
420	      for (let i = 0; i < word.length; i++){
421	        const ch = word[i];
422	        if ('AUX'.indexOf(ch) < 0) continue;
423	        let pen;
424	        try { pen = text.getStartPositionOfChar(i).x; } catch(e){ continue; }
425	        const r = inkScan(ch, fam);
426	        const polys = ch === 'X' ? r.polyRows.concat(r.polyCols) : r.polyRows;
427	        polys.forEach(pts => {
