437	  /* ---------- geometri för affischen ---------- */
438	  const G = { P:100, F:400, S0:4, contentW:1000, hHero:[73,73], hTarget:[90,90], gapT:4, centerEnd:0, ready:false };
439	  function layout(){
440	    const P = parseFloat(getComputedStyle(fbs[0].querySelector('.poster')).fontSize);
441	    const contentW = stage.clientWidth - 2 * parseFloat(getComputedStyle(stage).paddingLeft);
442	    const narrow = innerWidth < 900;
443	    // mät målraderna i vila
444	    fbs.forEach(f => { f.style.width = contentW + 'px'; f.style.transform = 'none'; f.style.visibility = 'hidden'; f.style.position = 'absolute'; });
445	    G.hTarget = fbs.map(f => f.offsetHeight);
446	    fbs.forEach(f => { f.style.visibility = ''; });
447	    // tillgänglig höjd för blocket (på smal skärm styr bredden ensam)
448	    const stageH = stage.clientHeight;
449	    const descBottom = block.offsetTop;
450	    const footH = foot.offsetHeight;
451	    const siteH = siteRow.offsetHeight + 18;
452	    const availH = narrow ? 1e6 : Math.max(120, stageH - descBottom - siteH - footH - 8);
453	    const widthLimit = (narrow ? 1.0 : 0.70) * contentW / 2.26;
454	    const F = Math.min(availH / 1.47, widthLimit, 900);
455	    const leadH = lead.offsetHeight + 18;
456	    const targetBlockH = G.hTarget[0] + G.hTarget[1] + 0.04 * P;
457	    G.centerEnd = narrow ? 0 : Math.max(0, (stageH - descBottom - targetBlockH - leadH - footH - 8) / 2);
458	    if (rm){
459	      // ingen resa: affischen står i sin egen storlek, rubriken ligger i flödet
460	      G.ready = false;
461	      svgs.forEach(sv => { sv.style.width = (2.26 * F) + 'px'; sv.style.height = (0.73 * F) + 'px'; });
462	      rows.forEach(r => { r.style.height = ''; r.style.width = ''; r.style.clipPath = ''; });
463	      fbs.forEach(f => { f.style.transform = ''; f.style.width = ''; f.style.opacity = ''; });
464	      fas.forEach(f => { f.style.transform = ''; f.style.opacity = ''; });
465	      block.style.transform = ''; block.style.height = ''; block.style.marginTop = '';
466	      siteRow.style.opacity = ''; claim.style.opacity = ''; claim.style.visibility = ''; lead.style.opacity = ''; lead.style.visibility = '';
467	      return;
468	    }
469	    // SVG-bredd i blockenheter: 2.26em av affischstorleken, skalas upp av blocket
470	    svgs.forEach(sv => { sv.style.width = (2.26 * P) + 'px'; sv.style.height = (0.73 * P) + 'px'; });
471	    G.P = P; G.F = F; G.S0 = F / P; G.contentW = contentW;
472	    G.hHero = [0.73 * P, 0.73 * P];
473	    G.gapT = 0.04 * P;
474	    G.ready = true;
475	    applyHero(heroP, true);
476	  }
