478	  /* ---------- scrollen ---------- */
479	  const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
480	  const lerp = (a, b, t) => a + (b - a) * t;
481	  const smooth = t => t * t * (3 - 2 * t);
482	  const easeIO = t => t < .5 ? 4*t*t*t : 1 - Math.pow(-2*t + 2, 3) / 2;
483	  let heroP = 0, heroTarget = 0, siteIdx = -1;
484	  const HOLD = 0.06, SLIDE_END = 0.58;
485	
486	  function stripPos(ps){
487	    // två byten med vila emellan: Calyx håller, byter till Hōrai, håller, byter till Hyperborea, håller
488	    const seg = [[0.12, 0.42], [0.58, 0.88]];
489	    let k = 0;
490	    seg.forEach(([a, b]) => { k += smooth(clamp((ps - a) / (b - a), 0, 1)); });
491	    return k;
492	  }
493	
494	  function applyHero(p, force){
495	    if (!G.ready) return;
496	    const ps = clamp((p - HOLD) / (SLIDE_END - HOLD), 0, 1);
497	    const pb = clamp((p - SLIDE_END) / (1 - SLIDE_END), 0, 1);
498	    // (1) bilden bakom masken glider
499	    const k = stripPos(ps);
500	    strips.forEach((g, i) => { g.setAttribute('transform', `translate(0 ${(i === 0 ? 0 : -73) - k * 234})`); });
501	    const idx = Math.round(k);
502	    if (idx !== siteIdx){ siteIdx = idx; siteRow.textContent = siteNames[idx]; }
503	    // (2) blocket andas
504	    const e = easeIO(pb);
505	    const s = lerp(G.S0, 1, e);
506	    block.style.transform = `scale(${s})`;
507	    const rowW = G.contentW / s;
508	    let visualH = 0;
509	    rows.forEach((row, i) => {
510	      const Hv = lerp(G.hHero[i] * G.S0, G.hTarget[i], e);   // visuell radhöjd i px
511	      const h = Hv / s;                                       // i blockenheter
512	      visualH += Hv + (i === 1 ? lerp(0, G.gapT, e) : 0);
513	      row.style.height = h + 'px';
514	      row.style.width = rowW + 'px';
515	      if (i === 1) row.style.marginTop = (lerp(0, G.gapT, e) / s) + 'px';
516	      // ordmärket glider en bit uppåt och tonar; rubriken kommer underifrån och tonar in: en korstoning i samma rörelse
517	      fas[i].style.transform = `translateY(${-0.4 * h * e}px)`;
518	      fas[i].style.opacity = 1 - clamp(e / 0.55, 0, 1);
519	      row.style.clipPath = `inset(${(-0.45 * G.P * clamp((e - 0.85) / 0.15, 0, 1)).toFixed(2)}px 0 0 0)`;
520	      fbs[i].style.transform = `translateY(${(0.4 * Hv + 0.35 * G.P) * (1 - e) / s}px) scale(${1 / s})`;
521	      fbs[i].style.opacity = clamp((e - 0.3) / 0.5, 0, 1);
522	      fbs[i].style.width = G.contentW + 'px';
523	    });
524	    block.style.height = visualH + 'px';
525	    block.style.marginTop = (G.centerEnd * e).toFixed(1) + 'px';
526	    const fade = 1 - clamp(pb * 2.2, 0, 1);
527	    const rise = clamp(pb * 2.2 - 1.2, 0, 1);
528	    siteRow.style.opacity = fade;
529	    claim.style.opacity = fade;
530	    lead.style.opacity = rise;
531	    claim.style.visibility = fade === 0 ? 'hidden' : '';
532	    lead.style.visibility = rise === 0 ? 'hidden' : '';
533	  }
