545	    }
546	    // akt 4: glid in en gång, svartvitt till mitten, sedan färg och öppen ram
547	    spreads.forEach((sp, i) => {
548	      const r = sp.getBoundingClientRect();
549	      if (!sp.classList.contains('in') && r.top < vh * 0.85 && r.bottom > 0) sp.classList.add('in');
