558	    lrows.forEach((el, i) => {
559	      if (el.classList.contains('in')) return;
560	      const r = el.getBoundingClientRect();
561	      if (r.top < vh * 0.88){ el.style.transitionDelay = (i * 120) + 'ms'; el.classList.add('in'); }
562	    });
563	    if (!rm && deskPhoto){
