388	
389	  /* ---- reveal-once, fails toward visible ---- */
390	  var rows = [].slice.call(document.querySelectorAll('[data-row], [data-spread]'));
391	  if (!reduce) {
392	    doc.classList.add('motion');
393	    var io = new IntersectionObserver(function(entries){
394	      entries.forEach(function(e){ if (e.isIntersecting){ e.target.classList.add('in'); io.unobserve(e.target); } });
395	    }, {threshold: 0, rootMargin: '0px 0px -8% 0px'});
396	    rows.forEach(function(el){
397	      var r = el.getBoundingClientRect();
398	      if (r.top < innerHeight) el.classList.add('in'); else io.observe(el);
399	    });
400	    setTimeout(function(){ rows.forEach(function(el){ el.classList.add('in'); }); }, 4000); /* failsafe */
401	  } else {
402	    rows.forEach(function(el){ el.classList.add('in'); });
403	  }
404	
405	  /* ---- spreads: printed plate turns to colour, then to the live frame ---- */
406	  var spreads = [].slice.call(document.querySelectorAll('[data-spread]'));
407	  if (reduce) {
408	    var io2 = new IntersectionObserver(function(entries){
409	      entries.forEach(function(e){ if (e.isIntersecting){ e.target.classList.add('live'); io2.unobserve(e.target); } });
410	    }, {threshold: 0.6});
411	    spreads.forEach(function(s){ io2.observe(s); });
412	  }
413	
414	  if (reduce) return;
415	
416	  /* ---- hero: the paper slides, the block breathes ---- */
417	  var hero = document.querySelector('.hero');
418	  var block = document.getElementById('block');
419	  var travel = document.querySelector('.travel');
420	  var lead = document.querySelector('.lead');
421	  var fsWord, fsHead, lhWord = 0.78, lhHead = 0.92, stickTop, start, span;
422	  var target = 0, cur = 0, forced = params.has('p') ? clamp(parseFloat(params.get('p')),0,1) : null;
423	
424	  function measure(){
425	    var cs = getComputedStyle(doc);
426	    fsWord = parseFloat(cs.getPropertyValue('--fs-word')) || parseFloat(getComputedStyle(block.querySelector('.word')).fontSize);
427	    var probe = document.createElement('span'); probe.style.cssText = 'position:absolute;visibility:hidden;font-size:var(--fs-head)'; document.body.appendChild(probe);
428	    fsHead = parseFloat(getComputedStyle(probe).fontSize); document.body.removeChild(probe);
429	    var probe2 = document.createElement('span'); probe2.style.cssText = 'position:absolute;visibility:hidden;font-size:var(--fs-word)'; document.body.appendChild(probe2);
430	    fsWord = parseFloat(getComputedStyle(probe2).fontSize); document.body.removeChild(probe2);
431	    stickTop = parseFloat(getComputedStyle(block).top);
432	    /* block height at rest and at the end of the breath */
433	    apply(0, true); var h0 = block.offsetHeight;
434	    apply(1, true); var h1 = block.offsetHeight;
435	    apply(cur, true);
436	    var heroTop = hero.getBoundingClientRect().top + scrollY;
437	    start = heroTop + lead.offsetHeight - stickTop;           /* block reaches the bar */
438	    span = travel.offsetHeight + (h0 - h1);                    /* block unsticks when its bottom meets the hero's end */
439	  }
440	
441	  function apply(p, silent){
442	    var s = block.style;
443	    /* phase 1: the image behind the mask travels, 0..0.55 */
444	    var a = seg(p, 0.10, 0.24), b = seg(p, 0.34, 0.48);
445	    s.setProperty('--sy', (-(a + b) * 33.3333) + '%');
446	    /* captions: out, then in, never both at once */
447	    var c1 = 1 - seg(p, 0.10, 0.16), c2 = seg(p, 0.18, 0.24) - seg(p, 0.34, 0.40), c3 = seg(p, 0.42, 0.48);
448	    s.setProperty('--c1', c1.toFixed(3)); s.setProperty('--c2', c2.toFixed(3)); s.setProperty('--c3', c3.toFixed(3));
449	    /* phase 2: the block breathes, 0.55..1 */
450	    var m = seg(p, 0.55, 1);
451	    var fs = fsWord + (fsHead - fsWord) * m;
452	    var lh = lhWord + (lhHead - lhWord) * m;
453	    s.setProperty('--fs', fs.toFixed(2) + 'px'); s.setProperty('--lh', lh.toFixed(4));
454	    s.setProperty('--fsh', (fsHead * (1 + 0.35 * (1 - m))).toFixed(2) + 'px');
455	    var wo = 1 - seg(p, 0.60, 0.80);
456	    s.setProperty('--wo', wo.toFixed(3)); s.setProperty('--wb', (seg(p, 0.58, 0.82) * 10).toFixed(2) + 'px');
457	    var ho = seg(p, 0.70, 0.92);
458	    s.setProperty('--ho', ho.toFixed(3)); s.setProperty('--hls', (0.06 - 0.09 * seg(p, 0.62, 1)).toFixed(4) + 'em');
459	    var po = 1 - seg(p, 0.55, 0.75);
460	    s.setProperty('--po', po.toFixed(3)); s.setProperty('--py', (-40 * (1 - po)).toFixed(1) + 'px');
461	    s.setProperty('--co', po.toFixed(3));
462	    if (!silent) block.dataset.p = p.toFixed(3);
463	  }
464	
465	  /* ---- other scroll-linked pieces ---- */
466	  var plateDoc = document.getElementById('plateDoc');
467	  var close = document.getElementById('close');
468	  function others(){
469	    var vh = innerHeight;
470	    spreads.forEach(function(sp){
471	      if (sp.classList.contains('live')) return;
472	      var r = sp.querySelector('.frame').getBoundingClientRect();
473	      var q = clamp((vh - r.top) / (vh * 0.5 + r.height * 0.5), 0, 1);
474	      sp.style.setProperty('--q', smooth(q).toFixed(3));
475	      if (q >= 0.999) sp.classList.add('live');
476	    });
477	    var pr = plateDoc.getBoundingClientRect();
478	    plateDoc.style.setProperty('--par', clamp(((pr.top + pr.height/2) - vh/2) * -0.10, -40, 40).toFixed(1) + 'px');
479	    var cr = close.getBoundingClientRect();
480	    /* the ink rolls down as the block enters; fully down by the time the page bottoms out */
481	    var d = 1 - smooth(clamp((vh - cr.top) / Math.min(vh * 0.75, cr.height), 0, 1));
482	    close.style.setProperty('--drop', (d * 100).toFixed(2) + '%');
483	  }
484	
485	  var raf = null;
486	  function frame(){
487	    raf = null;
488	    cur += (target - cur) * 0.14;
489	    if (Math.abs(target - cur) < 0.0004) cur = target;
490	    apply(cur);
491	    if (cur !== target) raf = requestAnimationFrame(frame);
492	  }
493	  function onScroll(){
494	    target = forced !== null ? forced : clamp((scrollY - start) / span, 0, 1);
495	    others();
496	    if (!raf) raf = requestAnimationFrame(frame);
497	  }
498	  function init(){ measure(); onScroll(); }
499	  if (document.fonts && document.fonts.ready) document.fonts.ready.then(init); else init();
500	  init();
501	  addEventListener('scroll', onScroll, {passive:true});
502	  addEventListener('resize', function(){ measure(); onScroll(); });
503	  addEventListener('load', function(){ measure(); onScroll(); });
504	})();
505	</script>
506	<noscript><style>.travel{display:none}</style></noscript>
507	</body>
508	</html>
